function enableAudio(){try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();masterGain=audio.createDynamicsCompressor();masterGain.threshold.value=-12;masterGain.knee.value=20;masterGain.ratio.value=4;masterGain.attack.value=.003;masterGain.release.value=.15;masterGain.connect(audio.destination);sfxGain=audio.createGain();musicGain=audio.createGain();sfxGain.connect(masterGain);musicGain.connect(masterGain);applyAudioVolumes();}if(audio.state==='suspended')audio.resume().catch(()=>{});}catch{}}
