function trackDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(Error('No local storage'));const r=window.indexedDB.open('bn89-music',1);r.onupgradeneeded=()=>r.result.createObjectStore('tracks');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
